import {skipToken} from '@reduxjs/toolkit/query'
import {memo, useCallback, useEffect, useMemo} from 'react'

import useMyId from '../../../hooks/useMyId'
import {restApi} from '../../../services/rest'
import {subscribeOnUserEvents} from '../../../utils/subscriber'
import {USER_PERMISSIONS_CHANGED} from '../../../utils/subscriptionEvents'
import {useSequenceLoaderReadyHandler} from '../SequenceLoader/SequenceLoader.hooks'

import ActionsDropdown from './ActionsDropdown'
import type {ActionsDropdownOwnProps} from './ActionsDropdown.types'
import {getActionsPath} from './ActionsDropdown.utils'

function ActionsDropdownContainer(props: ActionsDropdownOwnProps) {
  const {entityHref, preload, inline, showAlways} = props
  const path = useMemo(() => getActionsPath(entityHref), [entityHref])
  const myId = useMyId()
  const {html} = restApi.endpoints.getHtml.useQueryState(path != null ? {path} : skipToken, {
    selectFromResult: ({data}) => ({html: data}),
  })
  const [fetchHtml] = restApi.endpoints.getHtml.useLazyQuerySubscription()
  const reload = useCallback(() => path != null && fetchHtml({path}), [fetchHtml, path])
  useEffect(
    () =>
      path != null && myId != null && (preload === true || inline !== true)
        ? subscribeOnUserEvents(`html:${path}`, myId, [USER_PERMISSIONS_CHANGED], reload)
        : undefined,
    [inline, myId, path, preload, reload],
  )
  useSequenceLoaderReadyHandler(showAlways || html != null)
  return (
    <ActionsDropdown
      {...props}
      path={path}
      html={html}
      htmlAvailable={html != null && html.trim() !== ''}
      reload={reload}
    />
  )
}

export default memo(ActionsDropdownContainer)
